// 真实未完服务及已有公开报告/消息都与旧实现逐字节比较；新扩展不能污染旧profile。
void legacy_bytes(){Fixture f;f.catalog.regional_life=false;const auto id=f.start(f.request("service"));check(f.growth.life_activities.empty(),"old service has no life evidence");CodecVisitor::Buffer before,after;CodecVisitor old_growth(before),new_growth(after);auto state=f.growth;good(legacy_visit_growth_checkpoint(old_growth,state));good(old_growth.finish());good(visit_growth_checkpoint(new_growth,state,false));good(new_growth.finish());check(before==after,"nonempty growth3 bytes equal eb64949");
    DynamicSocialState social;social.version=1;social.last_collected_tick=1;Report report;report.id="report:supply:1";report.fact_id="supply:1";report.payload_kind="local_supply_observation";report.origin_subject={SubjectKind::organization,"market"};report.observation_tick=1;report.visibility_scope=ReportVisibility::local_public;report.reliability_kind=ReportReliability::official;report.observation.id=report.fact_id;report.observation.kind=report.payload_kind;report.observation.rule_version="local_economy_v1";report.observation.tick=1;report.observation.publicly_visible=true;report.observation.supply=SupplyObservation{"market.grain","market","town","employer.bag","grain",report.fact_id,20,10,1};social.reports.insert(report.id,report);PendingMessage message{"message:2",report.id,report.origin_subject,{SubjectKind::actor,"worker"},"official_supply_report",1,2,MessageStatus::pending,{}};social.pending_messages.insert(message.id,message);OrderedTable<KnownReport> known;known.insert(report.id,{report.origin_subject,report.id,{},1,report.origin_subject});social.known_reports.insert("1:market",known);CodecVisitor old_social(before),new_social(after);good(legacy_visit_dynamic_social_checkpoint(old_social,social));good(old_social.finish());good(visit_dynamic_social_checkpoint(new_social,social));good(new_social.finish());check(before==after,"nonempty dynamic_social1 bytes equal eb64949");
}
