// 单次执行只覆盖本批证据与其资产/知识消费者；失败输出原断言供中央保留。
int main(){try{work_and_restore();refusal_and_cancellation();reports_and_visibility();asking_news();retention();legacy_codec();
#ifdef HANMO_LIFE_LEGACY_ORACLE
legacy_bytes();
#endif
std::cout<<"REGIONAL_LIFE_EVIDENCE_CHECKS="<<checks<<" FAILURES=0\n";return 0;}catch(const std::exception& error){std::cerr<<"REGIONAL_LIFE_EVIDENCE_FAILURE="<<error.what()<<" CHECKS="<<checks<<"\n";return 1;}}
